CREATE TABLE IF NOT EXISTS ik_d1_preparation_steps (id TEXT PRIMARY KEY, destination TEXT NOT NULL, namespace TEXT NOT NULL, mapping_version TEXT NOT NULL, principal_id TEXT NOT NULL, operation_key TEXT NOT NULL, reversal_policy TEXT NOT NULL, codec_id TEXT, source_digest TEXT NOT NULL, total INTEGER NOT NULL, records INTEGER NOT NULL DEFAULT 0, stages TEXT NOT NULL DEFAULT '[]', phase TEXT NOT NULL CHECK(phase IN ('collecting','hashing','combining','prepared')), hash_json TEXT, fingerprint TEXT, verified_revision INTEGER, revision INTEGER NOT NULL DEFAULT 0, UNIQUE(destination,principal_id,operation_key));

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_binding BEFORE UPDATE OF id,destination,namespace,mapping_version,principal_id,operation_key,reversal_policy,codec_id,source_digest,total ON ik_d1_preparation_steps BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_BINDING_CHANGED'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_revision BEFORE UPDATE ON ik_d1_preparation_steps WHEN NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_CHANGED'); END;

CREATE TABLE IF NOT EXISTS ik_d1_stream_sources (stream_id TEXT PRIMARY KEY REFERENCES ik_d1_streams(id) ON DELETE CASCADE, destination TEXT NOT NULL, source_digest TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS ik_d1_retirements (id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('job','stream')), destination TEXT NOT NULL, receipt_id TEXT NOT NULL, retired_at TEXT NOT NULL, PRIMARY KEY(id, kind));

CREATE TABLE IF NOT EXISTS ik_d1_erasure_journal (id TEXT PRIMARY KEY, destination TEXT NOT NULL, recorded_at TEXT NOT NULL, records_erased INTEGER NOT NULL CHECK(records_erased>=0), jobs_retired INTEGER NOT NULL CHECK(jobs_retired>=0), streams_retired INTEGER NOT NULL CHECK(streams_retired>=0), stores_json TEXT NOT NULL CHECK(json_valid(stores_json)));

CREATE INDEX IF NOT EXISTS ik_d1_erasure_journal_time ON ik_d1_erasure_journal(destination, recorded_at);

CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_insert BEFORE INSERT ON ik_d1_erasure_journal WHEN EXISTS(SELECT 1 FROM ik_d1_erasure_journal WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_insert BEFORE INSERT ON ik_d1_retirements WHEN EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=NEW.id AND kind=NEW.kind) BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_update BEFORE UPDATE ON ik_d1_erasure_journal BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_delete BEFORE DELETE ON ik_d1_erasure_journal BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_update BEFORE UPDATE ON ik_d1_retirements BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_delete BEFORE DELETE ON ik_d1_retirements BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;

CREATE TABLE IF NOT EXISTS ik_d1_erasure_tally (receipt_id TEXT NOT NULL, store TEXT NOT NULL, image TEXT NOT NULL);

DROP TRIGGER IF EXISTS ik_d1_stream_revision_update;

CREATE TRIGGER ik_d1_stream_revision_update BEFORE UPDATE ON ik_d1_stream_revisions WHEN NEW.stream_id IS NOT OLD.stream_id OR NEW.destination IS NOT OLD.destination OR NEW.mapping_version IS NOT OLD.mapping_version OR NEW.principal_id IS NOT OLD.principal_id OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.total IS NOT OLD.total OR NEW.layout_hash IS NOT OLD.layout_hash OR NEW.layout_revision<OLD.layout_revision OR NEW.progress_revision<=OLD.progress_revision OR ((NEW.namespace IS NOT OLD.namespace OR NEW.operation_key IS NOT OLD.operation_key) AND NOT (NEW.namespace='' AND NEW.operation_key='' AND NOT EXISTS(SELECT 1 FROM ik_d1_streams WHERE id=OLD.stream_id) AND EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=OLD.stream_id AND kind='stream'))) BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_REVISION_CHANGED'); END;

-- ORD-002: saved shopping lists. Desired SKUs, selling units and quantities only; never prices, stock or promises.
CREATE TABLE bw_lists (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, name TEXT NOT NULL, created_by TEXT NOT NULL, value_json TEXT NOT NULL CHECK(json_valid(value_json)), revision TEXT NOT NULL);
CREATE INDEX bw_lists_account ON bw_lists(account_id, created_by);

-- ORD-004: negotiated wholesale quotes. order_id links the one order an accepted quote converted into.
CREATE TABLE bw_quotes (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, value_json TEXT NOT NULL CHECK(json_valid(value_json)), revision TEXT NOT NULL, order_id TEXT UNIQUE);
CREATE INDEX bw_quotes_account ON bw_quotes(account_id);

-- ORD-005: the quote conversation beside bw_quotes. Entries are buyer-visible messages or supplier-only internal notes,
-- with at most one attached PDF/PNG/JPEG; Barrow has no door that edits or deletes them. Notices tell the other side
-- (the account's buyer, or the supplier staff acting for the rep) that something changed, until they read the quote.
CREATE TABLE bw_quote_entries (id TEXT PRIMARY KEY, quote_id TEXT NOT NULL REFERENCES bw_quotes(id), account_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('message','internal')), side TEXT NOT NULL CHECK(side IN ('buyer','supplier')), author_id TEXT NOT NULL, author_email TEXT NOT NULL, body TEXT NOT NULL, quote_revision INTEGER NOT NULL, created_at TEXT NOT NULL, attachment_name TEXT, attachment_type TEXT CHECK(attachment_type IS NULL OR attachment_type IN ('application/pdf','image/png','image/jpeg')), attachment_size INTEGER CHECK(attachment_size IS NULL OR attachment_size BETWEEN 1 AND 1048576), attachment_sha256 TEXT, attachment_base64 TEXT);
CREATE INDEX bw_quote_entries_quote ON bw_quote_entries(quote_id);
CREATE TABLE bw_quote_notices (id TEXT PRIMARY KEY, quote_id TEXT NOT NULL REFERENCES bw_quotes(id), account_id TEXT NOT NULL, audience TEXT NOT NULL CHECK(audience IN ('buyer','supplier')), kind TEXT NOT NULL CHECK(kind IN ('requested','message','internal','revision','accepted')), summary TEXT NOT NULL, actor_id TEXT NOT NULL, created_at TEXT NOT NULL, read_by TEXT, read_at TEXT);
CREATE INDEX bw_quote_notices_quote ON bw_quote_notices(quote_id, audience);

-- ACC-003: an account's bill-to, ship-to and contact records. Edits replace value_json under a new revision; orders keep
-- their own snapshot, so an edit never rewrites an order. Archived records stay for history and cannot be chosen.
CREATE TABLE bw_locations (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('bill-to','ship-to','contact')), value_json TEXT NOT NULL CHECK(json_valid(value_json)), revision TEXT NOT NULL, is_default INTEGER NOT NULL DEFAULT 0 CHECK(is_default IN (0,1)), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)));
CREATE INDEX bw_locations_account ON bw_locations(account_id, kind);
CREATE UNIQUE INDEX bw_locations_default ON bw_locations(account_id, kind) WHERE is_default=1;

-- REP-004: immutable approval-time attribution stays with internal supplier records.
CREATE TABLE bw_order_commissions (
 order_id TEXT PRIMARY KEY REFERENCES bw_orders(id),
 value_json TEXT NOT NULL
);

-- RPT-006: deterministic chronological and ship-window page ordering.
CREATE INDEX bw_orders_prepared ON bw_orders(json_extract(value_json,'$.preparedAt'),id);
CREATE INDEX bw_orders_ship_window ON bw_orders((json_extract(value_json,'$.requestedDate') IS NULL OR json_extract(value_json,'$.requestedDate')=''),json_extract(value_json,'$.requestedDate'),id);

-- RPT-006: immutable saved definitions and one frozen result per schedule/period.
CREATE TABLE bw_report_schedules (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, report_type TEXT NOT NULL CHECK(report_type IN ('sales','finance')),
 filters_json TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL, next_at TEXT NOT NULL,
 restored INTEGER NOT NULL DEFAULT 0 CHECK(restored IN (0,1))
);
CREATE TABLE bw_report_recipients (
 schedule_id TEXT NOT NULL REFERENCES bw_report_schedules(id), operator_id TEXT NOT NULL,
 operator_version INTEGER NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin')), removed_at TEXT,
 PRIMARY KEY(schedule_id,operator_id)
);
CREATE TABLE bw_report_runs (
 id TEXT PRIMARY KEY, schedule_id TEXT NOT NULL REFERENCES bw_report_schedules(id), period TEXT NOT NULL,
 from_date TEXT NOT NULL, to_date TEXT NOT NULL, as_of TEXT NOT NULL, expires_at TEXT NOT NULL,
 snapshot_json TEXT NOT NULL, UNIQUE(schedule_id,period)
);
CREATE TABLE bw_report_deliveries (
 id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES bw_report_runs(id), operator_id TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'queued', reason TEXT, provider_message_id TEXT, recipient TEXT,
 updated_at TEXT NOT NULL, UNIQUE(run_id,operator_id)
);
CREATE INDEX bw_report_dispatch ON bw_report_deliveries(status);
-- Identity revocation cancels unsent deliveries in the same transaction as the native change.
CREATE TRIGGER bw_report_operator_revoked AFTER UPDATE OF role,status,version ON oa_operators
WHEN NEW.role<>OLD.role OR NEW.status<>OLD.status OR NEW.version<>OLD.version
BEGIN
 UPDATE bw_report_deliveries SET status='cancelled',reason='recipient identity, role or account version changed',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
 WHERE operator_id=NEW.id AND status IN ('queued','not configured');
 INSERT INTO bw_audit(id,subject_id,actor_id,action,created_at,context_json)
 SELECT lower(hex(randomblob(16))),NEW.id,'system:reports','report.recipient-revoked',strftime('%Y-%m-%dT%H:%M:%fZ','now'),
 json_object('revision',CAST(NEW.version AS TEXT),'source','operator.update','reason','Recipient identity, role or account version changed; queued reports cancelled and downloads recheck entitlement.')
 WHERE EXISTS(SELECT 1 FROM bw_report_recipients WHERE operator_id=NEW.id);
END;

-- ORD-015: published sales terms are append-only versions per series. An account is assigned a series and, where it
-- requires acceptance, must accept the series' newest version at submission. The acceptance itself lives on the order
-- (and its confirmation snapshot); a rep-captured signature image is kept beside it by order ID.
CREATE TABLE bw_sales_terms (series TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>=1), title TEXT NOT NULL, body TEXT NOT NULL, content_sha256 TEXT NOT NULL, pdf_name TEXT, pdf_size INTEGER, pdf_sha256 TEXT, pdf_base64 TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(series,version));
CREATE TABLE bw_terms_assignments (account_id TEXT PRIMARY KEY REFERENCES bw_accounts(id), series TEXT NOT NULL, require_acceptance INTEGER NOT NULL CHECK(require_acceptance IN (0,1)), assigned_by TEXT NOT NULL, assigned_at TEXT NOT NULL);
CREATE TABLE bw_terms_signatures (order_id TEXT PRIMARY KEY REFERENCES bw_orders(id), sha256 TEXT NOT NULL, png_base64 TEXT NOT NULL);

CREATE TABLE bw_applications(id TEXT PRIMARY KEY,value_json TEXT NOT NULL,revision TEXT NOT NULL,state TEXT NOT NULL,account_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE bw_application_intake(id TEXT PRIMARY KEY,value_json TEXT NOT NULL,revision TEXT NOT NULL,state TEXT NOT NULL,account_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE bw_application_codes(application_id TEXT PRIMARY KEY,code_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE bw_application_sessions(digest TEXT PRIMARY KEY,application_id TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE bw_application_documents(id TEXT PRIMARY KEY,application_id TEXT NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,content_base64 TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE bw_application_history(id TEXT PRIMARY KEY,application_id TEXT NOT NULL,state TEXT NOT NULL,reason TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE bw_application_rates(digest TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE bw_usage_terms(version INTEGER PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,sha256 TEXT NOT NULL,pdf_json TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE bw_usage_acceptances(user_id TEXT NOT NULL,version INTEGER NOT NULL,sha256 TEXT NOT NULL,accepted_at TEXT NOT NULL,PRIMARY KEY(user_id,version));

-- ACC-002 authority belongs to Barrow, never to a broader Base member role.
CREATE TABLE bw_company_members (
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES bw_accounts(id),
 user_id TEXT NOT NULL, email TEXT NOT NULL, email_key TEXT NOT NULL, display_name TEXT NOT NULL,
 policy_json TEXT NOT NULL CHECK(json_valid(policy_json)),
 state TEXT NOT NULL CHECK(state IN ('invited','active','removed')),
 revision TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, erased_at TEXT
);
CREATE UNIQUE INDEX bw_company_person ON bw_company_members(user_id) WHERE state IN ('invited','active');
CREATE UNIQUE INDEX bw_company_email ON bw_company_members(email_key) WHERE state IN ('invited','active');
CREATE INDEX bw_company_account ON bw_company_members(account_id,state);
-- This marker prevents a removed legacy administrator from being re-created on sign-in.
CREATE TABLE bw_company_legacy_accounts (account_id TEXT PRIMARY KEY REFERENCES bw_accounts(id));
CREATE TABLE bw_company_invites (
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES bw_accounts(id), member_id TEXT,
 email TEXT NOT NULL, email_key TEXT NOT NULL, display_name TEXT NOT NULL,
 token_hash TEXT UNIQUE, policy_json TEXT NOT NULL CHECK(json_valid(policy_json)),
 status TEXT NOT NULL CHECK(status IN ('requested','collision','accepted','revoked','expired')),
 collision_reason TEXT, expires_at INTEGER NOT NULL, accepted_by TEXT,
 created_by TEXT NOT NULL, issuer_version INTEGER NOT NULL, issuer_member_revision TEXT,
 created_at TEXT NOT NULL, reason TEXT NOT NULL, revision TEXT NOT NULL,
 delivery_status TEXT NOT NULL DEFAULT 'pending'
);
CREATE INDEX bw_company_invite_account ON bw_company_invites(account_id,created_at);
CREATE INDEX bw_company_invite_email ON bw_company_invites(email_key,status);
-- ASCII legacy accounts migrate in the installation transaction. Runtime bootstrap
-- also handles Unicode normalization and buyers invited after this migration.
INSERT INTO bw_company_members(id,account_id,user_id,email,email_key,display_name,policy_json,state,revision,created_at,updated_at)
SELECT 'legacy:'||p.id,a.id,p.id,p.email,lower(trim(p.email)),p.display_name,
 '{"rights":["administrator","purchaser","approver","finance"],"locations":"all","perOrderLimitCents":null,"approvalLimitCents":null}',
 'active',lower(hex(randomblob(16))),strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now')
FROM bw_accounts a JOIN oa_operators p ON p.email=json_extract(a.value_json,'$.email') COLLATE BINARY
WHERE p.status='active' AND p.role='member';
INSERT INTO bw_company_legacy_accounts(account_id) SELECT account_id FROM bw_company_members;
-- In-app notices are side-wide today; recipient mail remains exact-user custody.
DROP TRIGGER bw_quote_notice_mail;
CREATE TRIGGER bw_quote_notice_mail AFTER INSERT ON bw_quote_notices WHEN NEW.mail_eligible=1
BEGIN
 INSERT INTO bw_quote_mail(id,notice_id,quote_id,account_id,audience,recipient_id,recipient,summary,actor_id,created_at,updated_at)
 SELECT lower(hex(randomblob(16))),NEW.id,NEW.quote_id,NEW.account_id,NEW.audience,p.id,p.email,NEW.summary,NEW.actor_id,NEW.created_at,NEW.created_at
 FROM oa_operators p WHERE p.status='active' AND (
  (NEW.audience='supplier' AND p.role IN ('owner','admin') AND p.id<>NEW.actor_id) OR
  (NEW.audience='buyer' AND p.role='member' AND EXISTS(SELECT 1 FROM bw_company_members cm
   WHERE cm.user_id=p.id AND cm.account_id=NEW.account_id AND cm.state='active' AND cm.erased_at IS NULL
   AND EXISTS(SELECT 1 FROM json_each(cm.policy_json,'$.rights') r WHERE r.value IN ('purchaser','approver'))))
 );
 INSERT INTO bw_quote_mail(id,notice_id,quote_id,account_id,audience,recipient_id,recipient,summary,actor_id,status,reason,created_at,updated_at)
 SELECT lower(hex(randomblob(16))),NEW.id,NEW.quote_id,NEW.account_id,'buyer',NULL,NULL,NEW.summary,NEW.actor_id,'withdrawn','no authorized buyer recipient',NEW.created_at,NEW.created_at
 WHERE NEW.audience='buyer' AND NOT EXISTS(SELECT 1 FROM oa_operators p JOIN bw_company_members cm ON cm.user_id=p.id
  WHERE p.status='active' AND p.role='member' AND cm.account_id=NEW.account_id AND cm.state='active' AND cm.erased_at IS NULL
  AND EXISTS(SELECT 1 FROM json_each(cm.policy_json,'$.rights') r WHERE r.value IN ('purchaser','approver')));
END;

-- ACC-005 authority is seed-owned. Native members remain members; invitations
-- confer no effective supplier authority until Native confirmation activates them.
CREATE TABLE bw_staff_members (
 user_id TEXT PRIMARY KEY,
 policy_json TEXT NOT NULL CHECK(json_valid(policy_json)),
 state TEXT NOT NULL CHECK(state IN ('active','revoked')),
 revision TEXT NOT NULL,
 native_version INTEGER NOT NULL CHECK(native_version > 0),
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL
);
-- Preserve saved owner/admin recipients while admitting version-pinned functional
-- members. Nullable revision is only valid for the existing native supplier roles.
DROP TRIGGER bw_report_operator_revoked;
CREATE TABLE bw_report_recipients_next (
 schedule_id TEXT NOT NULL REFERENCES bw_report_schedules(id), operator_id TEXT NOT NULL,
 operator_version INTEGER NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','member')), removed_at TEXT,
 staff_grant_revision TEXT,
 PRIMARY KEY(schedule_id,operator_id),
 CHECK(role<>'member' OR staff_grant_revision IS NOT NULL)
);
INSERT INTO bw_report_recipients_next(schedule_id,operator_id,operator_version,role,removed_at)
 SELECT schedule_id,operator_id,operator_version,role,removed_at FROM bw_report_recipients;
DROP TABLE bw_report_recipients;
ALTER TABLE bw_report_recipients_next RENAME TO bw_report_recipients;
CREATE TRIGGER bw_report_operator_revoked AFTER UPDATE OF role,status,version ON oa_operators
WHEN NEW.role<>OLD.role OR NEW.status<>OLD.status OR NEW.version<>OLD.version
BEGIN
 UPDATE bw_report_deliveries SET status='cancelled',reason='recipient identity, role or account version changed',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
 WHERE operator_id=NEW.id AND status IN ('queued','not configured');
 INSERT INTO bw_audit(id,subject_id,actor_id,action,created_at,context_json)
 SELECT lower(hex(randomblob(16))),NEW.id,'system:reports','report.recipient-revoked',strftime('%Y-%m-%dT%H:%M:%fZ','now'),
 json_object('revision',CAST(NEW.version AS TEXT),'source','operator.update','reason','Recipient identity, role or account version changed; queued reports cancelled and downloads recheck entitlement.')
 WHERE EXISTS(SELECT 1 FROM bw_report_recipients WHERE operator_id=NEW.id);
END;
-- A queued snapshot must never outlive the seed authority that admitted it.
CREATE TRIGGER bw_report_staff_revoked AFTER UPDATE OF revision,state,native_version ON bw_staff_members
WHEN NEW.revision<>OLD.revision OR NEW.state<>OLD.state OR NEW.native_version<>OLD.native_version
BEGIN
 UPDATE bw_report_deliveries SET status='cancelled',reason='recipient staff grant changed',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
 WHERE operator_id=NEW.user_id AND status IN ('queued','not configured');
END;

-- ACC-007: company approval routes, their saved revisions and dated delegations. Orders freeze the route they start
-- with in their own record, so these tables only ever govern requests that have not yet begun.
CREATE TABLE bw_company_routes (
 account_id TEXT PRIMARY KEY REFERENCES bw_accounts(id),
 policy_json TEXT NOT NULL CHECK(json_valid(policy_json)),
 revision TEXT NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE bw_company_route_versions (
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES bw_accounts(id), revision TEXT NOT NULL,
 policy_json TEXT NOT NULL CHECK(json_valid(policy_json)), saved_by TEXT NOT NULL, saved_at TEXT NOT NULL, reason TEXT NOT NULL
);
CREATE INDEX bw_company_route_versions_account ON bw_company_route_versions(account_id,saved_at);
CREATE TABLE bw_company_delegations (
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES bw_accounts(id),
 delegator_id TEXT NOT NULL, delegate_id TEXT NOT NULL,
 starts_on TEXT NOT NULL CHECK(starts_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
 ends_on TEXT NOT NULL CHECK(ends_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
 state TEXT NOT NULL CHECK(state IN ('active','ended')), revision TEXT NOT NULL, reason TEXT NOT NULL,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 CHECK(ends_on>=starts_on), CHECK(delegator_id<>delegate_id)
);
CREATE INDEX bw_company_delegations_account ON bw_company_delegations(account_id,state);

-- DATA-003: receipts carry opaque attribution and counts, never erased values.
ALTER TABLE bw_retention_requests ADD COLUMN requester TEXT NOT NULL DEFAULT 'Signed-in owner';
ALTER TABLE bw_retention_requests ADD COLUMN channel TEXT NOT NULL DEFAULT 'Owner review';
ALTER TABLE bw_retention_requests ADD COLUMN verification_note TEXT NOT NULL DEFAULT 'Verified through the current owner session';
CREATE TABLE bw_account_erasure_journal (
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL, fingerprint TEXT NOT NULL,
 receipt_json TEXT NOT NULL CHECK(json_valid(receipt_json))
);

-- Deployment credentials remain in encrypted platform bindings, never the archive or audit.
CREATE TABLE bw_connector_config (id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, revision TEXT NOT NULL);
-- Per-installation keyed IP digests, bounded to their short fixed window.
CREATE TABLE bw_request_rates (digest TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX bw_request_rates_expiry ON bw_request_rates(expires_at);

CREATE TABLE bw_line_sheets (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, value_json TEXT NOT NULL, revision TEXT NOT NULL);
CREATE INDEX bw_line_sheets_account ON bw_line_sheets(account_id);
CREATE TABLE bw_sheet_events (id TEXT PRIMARY KEY, sheet_id TEXT NOT NULL, account_id TEXT NOT NULL, actor_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('open','view')), skus_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX bw_sheet_events_account ON bw_sheet_events(account_id,created_at);

-- ORD-014: an order may record any number of revised confirmations; submitted and accepted stay once per order.
CREATE TABLE bw_confirmations_revised (
 order_id TEXT NOT NULL,
 number INTEGER NOT NULL,
 stage TEXT NOT NULL,
 created_at TEXT NOT NULL,
 value_json TEXT NOT NULL,
 PRIMARY KEY(order_id,number)
);
INSERT INTO bw_confirmations_revised(order_id,number,stage,created_at,value_json) SELECT order_id,number,stage,created_at,value_json FROM bw_confirmations;
DROP TABLE bw_confirmations;
ALTER TABLE bw_confirmations_revised RENAME TO bw_confirmations;
CREATE UNIQUE INDEX bw_confirmations_once ON bw_confirmations(order_id,stage) WHERE stage IN ('submitted','accepted');

-- Outbound subscriptions are explicit installation settings and never portable credentials.
CREATE TABLE bw_webhook_subscriptions (
 id TEXT PRIMARY KEY, endpoint TEXT NOT NULL, event_types TEXT NOT NULL,
 secret_cipher TEXT, revision TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('active','revoked')),
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 lease_until INTEGER NOT NULL DEFAULT 0, next_delivery_at INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE bw_webhook_events (
 id TEXT PRIMARY KEY, envelope TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE bw_webhook_deliveries (
 id TEXT PRIMARY KEY, subscription_id TEXT NOT NULL, event_id TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','sending','retrying','dead-letter','acknowledged')),
 attempts INTEGER NOT NULL DEFAULT 0, cycle_attempts INTEGER NOT NULL DEFAULT 0,
 next_attempt_at INTEGER NOT NULL DEFAULT 0, lease_until INTEGER NOT NULL DEFAULT 0,
 acknowledged_at TEXT, last_result TEXT NOT NULL DEFAULT 'Locally queued; no external acceptance',
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 UNIQUE(subscription_id,event_id)
);
CREATE INDEX bw_webhook_due ON bw_webhook_deliveries(subscription_id,state,next_attempt_at);
CREATE TABLE bw_webhook_attempts (
 id TEXT PRIMARY KEY, delivery_id TEXT NOT NULL, event_id TEXT NOT NULL,
 number INTEGER NOT NULL, signing_revision TEXT NOT NULL, started_at TEXT NOT NULL,
 finished_at TEXT, http_status INTEGER, result TEXT NOT NULL,
 UNIQUE(delivery_id,number)
);
CREATE TRIGGER bw_webhook_event_immutable_update BEFORE UPDATE ON bw_webhook_events BEGIN SELECT RAISE(ABORT,'immutable_webhook_event'); END;
CREATE TRIGGER bw_webhook_event_immutable_delete BEFORE DELETE ON bw_webhook_events BEGIN SELECT RAISE(ABORT,'immutable_webhook_event'); END;
CREATE TRIGGER bw_webhook_attempt_retained BEFORE DELETE ON bw_webhook_attempts BEGIN SELECT RAISE(ABORT,'retained_webhook_attempt'); END;
CREATE TRIGGER bw_webhook_attempt_final BEFORE UPDATE ON bw_webhook_attempts
WHEN OLD.finished_at IS NOT NULL OR NEW.id<>OLD.id OR NEW.delivery_id<>OLD.delivery_id OR NEW.event_id<>OLD.event_id OR NEW.number<>OLD.number OR NEW.signing_revision<>OLD.signing_revision OR NEW.started_at<>OLD.started_at
BEGIN SELECT RAISE(ABORT,'immutable_webhook_attempt'); END;
-- Same transaction as the business audit. No names, addresses, prices, body, reason or documents.
-- A revision is the monotonically increasing local audit ordinal, not arbitrary context text.
CREATE TRIGGER bw_audit_outbound AFTER INSERT ON bw_audit
WHEN NEW.action IN ('account.saved','order.submitted','order.approved','quote.requested','quote.accepted')
 AND EXISTS(SELECT 1 FROM bw_webhook_subscriptions s WHERE s.state='active' AND s.secret_cipher IS NOT NULL AND NEW.action IN (SELECT value FROM json_each(s.event_types)))
BEGIN
 INSERT INTO bw_webhook_events(id,envelope,created_at) VALUES(NEW.id,json_object('schema','barrow.event.v1','id',NEW.id,'type',NEW.action,'occurredAt',NEW.created_at,'revision',NEW.rowid),NEW.created_at);
 INSERT INTO bw_webhook_deliveries(id,subscription_id,event_id,created_at,updated_at)
 SELECT lower(hex(randomblob(16))),s.id,NEW.id,NEW.created_at,NEW.created_at FROM bw_webhook_subscriptions s
 WHERE s.state='active' AND s.secret_cipher IS NOT NULL AND NEW.action IN (SELECT value FROM json_each(s.event_types));
END;
-- Receipt outcomes describe authenticated current provider doors, with no address/body copy.
CREATE TABLE bw_webhook_incoming (
 id TEXT PRIMARY KEY, provider TEXT NOT NULL, namespace TEXT NOT NULL, event_id TEXT NOT NULL,
 occurred_at INTEGER NOT NULL, received_at TEXT NOT NULL,
 outcome TEXT NOT NULL CHECK(outcome IN ('stored','duplicate')), applied INTEGER NOT NULL CHECK(applied IN (0,1))
);
CREATE INDEX bw_webhook_incoming_identity ON bw_webhook_incoming(provider,namespace,event_id);
CREATE TRIGGER bw_webhook_incoming_immutable_update BEFORE UPDATE ON bw_webhook_incoming BEGIN SELECT RAISE(ABORT,'immutable_webhook_intake'); END;
CREATE TRIGGER bw_webhook_incoming_immutable_delete BEFORE DELETE ON bw_webhook_incoming BEGIN SELECT RAISE(ABORT,'immutable_webhook_intake'); END;
CREATE TRIGGER bw_webhook_delivery_retained BEFORE DELETE ON bw_webhook_deliveries BEGIN SELECT RAISE(ABORT,'retained_webhook_delivery'); END;
CREATE TRIGGER bw_webhook_delivery_identity BEFORE UPDATE ON bw_webhook_deliveries
WHEN NEW.id<>OLD.id OR NEW.subscription_id<>OLD.subscription_id OR NEW.event_id<>OLD.event_id OR NEW.created_at<>OLD.created_at
BEGIN SELECT RAISE(ABORT,'immutable_webhook_delivery_identity'); END;

-- A destination run owns this session until completion or an explicit timeout.
-- Provider writes are preceded by retained immutable delivery bytes.
ALTER TABLE bw_delta_cutovers ADD COLUMN io_token TEXT;
ALTER TABLE bw_delta_cutovers ADD COLUMN io_until INTEGER NOT NULL DEFAULT 0;
-- All native mutation doors, including later ones, share the in-flight fence.
CREATE TRIGGER bw_delta_order_update BEFORE UPDATE ON bw_orders
WHEN EXISTS(SELECT 1 FROM bw_delta_cutovers d,json_each(d.scope_json) s
 WHERE s.value=OLD.account_id AND d.io_until>CAST(strftime('%s','now') AS INTEGER)*1000)
BEGIN SELECT RAISE(ABORT,'DELTA_IO_HELD'); END;

